 main(()->{keyInput.setText("bad-key");click(byText(config.getWindow().getDecorView(),"保存连接"));});check(config.isShowing(),"malformed Key keeps settings open for correction");main(()->{keyInput.setText("sk-invalid-test");click(byText(config.getWindow().getDecorView(),"测试连接"));});await(()->text(config.getWindow().getDecorView()).contains("API Key 无效"),"Key error");check(true,"invalid Key shows actionable connection error");shot("key_error");main(()->{keyInput.setText("sk-test-placeholder");click(byText(config.getWindow().getDecorView(),"保存连接"));});check(((EditText)field("input")).getText().toString().equals("这是尚未发送的提问"),"connection setup preserves unsent question");main(()->config.dismiss());await(()->((TextView)field("balanceLine")).getText().toString().contains("12.34"),"balance header");
 main(()->invoke("showBalance"));Dialog balance=(Dialog)field("lastSheet");await(()->text(balance.getWindow().getDecorView()).contains("10.34"),"balance details");check(true,"balance details include paid and grant amounts with update time");shot("balance");main(()->balance.dismiss());
 main(()->{try{((EditText)field("input")).setText("");}catch(Exception e){throw new RuntimeException(e);}});File document=new File(getTargetContext().getFilesDir(),"体验流程资料.txt");try(FileOutputStream out=new FileOutputStream(document)){out.write("这是可预览的资料正文。\n\n重点：预览在本地完成，发送后由 DeepSeek 处理。".getBytes("UTF-8"));}pickFile(document);check(((List<?>)field("pending")).size()==1,"system picker result parses into removable attachment");JSONObject attachment=(JSONObject)((List<?>)field("pending")).get(0);main(()->invoke("showFile",new Class<?>[]{JSONObject.class},new Object[]{attachment}));Dialog preview=(Dialog)field("lastSheet");check(text(preview.getWindow().getDecorView()).contains("这是可预览的资料正文"),"text attachment has readable local preview");shot("attachment_preview");main(()->preview.dismiss());main(()->{try{for(View view:views(activity.getWindow().getDecorView()))if(view.getContentDescription()!=null&&view.getContentDescription().toString().startsWith("移除附件：")){view.performClick();break;}}catch(Exception e){throw new RuntimeException(e);}});check(((List<?>)field("pending")).isEmpty()&&!((Button)field("send")).isEnabled(),"removing last attachment restores empty composer state");
 File bad=new File(getTargetContext().getFilesDir(),"损坏的文档.pdf");try(FileOutputStream out=new FileOutputStream(bad)){out.write("not a valid pdf".getBytes("UTF-8"));}pickFile(bad);await(()->accessibleText("文件处理提示"),"parse error");check(!(Boolean)field("reading"),"file parse failure restores usable composer");shot("file_error");tapAccessible("关闭");waitForIdleSync();
 JSONObject fixture=new JSONObject().put("id","flow-record").put("title","公式与代码的阅读").put("updated",System.currentTimeMillis()).put("messages",new JSONArray().put(new JSONObject().put("id","flow-u").put("role","user").put("text","请解释这个二阶系统。").put("status","complete")).put(new JSONObject().put("id","flow-a").put("role","assistant").put("text","## 二阶系统\n\n这里给出一个清晰的传递函数：\n\n\\[G(s)=\\frac{100}{s^2+14s+100}\\]\n\n\u0060\u0060\u0060python\nimport numpy as np\nprint(np.array([[0, 1], [-100, -14]]))\n\u0060\u0060\u0060").put("status","complete")));
 main(()->{try{JSONObject state=(JSONObject)field("state");state.put("chats",new JSONArray().put(fixture));state.put("current","flow-record");invoke("restoreDraft");invoke("render");invoke("history");}catch(Exception e){throw new RuntimeException(e);}});Dialog history=(Dialog)field("lastSheet");EditText search=null;for(View view:views(history.getWindow().getDecorView()))if(view instanceof EditText)search=(EditText)view;final EditText query=search;main(()->query.setText("公式"));check(text(history.getWindow().getDecorView()).contains("公式与代码的阅读"),"history search finds matching title");shot("history_search");main(()->history.dismiss());
 main(()->invoke("settings"));Dialog settings=(Dialog)field("lastSheet");main(()->click(byText(settings.getWindow().getDecorView(),"数据管理")));File backup=new File(getTargetContext().getFilesDir(),"flow-backup.json");ActivityMonitor export=addMonitor(pickerFilter(Intent.ACTION_CREATE_DOCUMENT),new ActivityResult(Activity.RESULT_OK,new Intent().setData(Uri.fromFile(backup))),true);main(()->click(byText(settings.getWindow().getDecorView(),"导出全部对话")));await(()->backup.exists()&&backup.length()>20,"backup export");removeMonitor(export);String exported;try(InputStream in=new FileInputStream(backup);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] chunk=new byte[4096];int count;while((count=in.read(chunk))!=-1)bytes.write(chunk,0,count);exported=bytes.toString("UTF-8");}check(new JSONObject(exported).getJSONArray("chats").length()==1&&!exported.contains("sk-test-placeholder"),"backup includes records and excludes API Key");
 main(()->{try{((JSONObject)field("state")).put("chats",new JSONArray());invoke("render");}catch(Exception e){throw new RuntimeException(e);}});importedFile(backup,settings);await(()->((JSONObject)field("state")).getJSONArray("chats").length()==1,"backup restore");check(true,"backup restore requires confirmation and recovers conversation");importedFile(backup,settings);check(((JSONObject)field("state")).getJSONArray("chats").length()==1,"importing backup twice does not duplicate existing IDs");
 main(()->{try{invoke("settings");Dialog actual=(Dialog)field("lastSheet");click(byText(actual.getWindow().getDecorView(),"外观与阅读"));click(byText(actual.getWindow().getDecorView(),"主题外观"));}catch(Exception e){throw new RuntimeException(e);}});tapAccessible("深色 · 夜森林");waitForIdleSync();Dialog readingSettings=(Dialog)field("lastSheet");main(()->click(byText(readingSettings.getWindow().getDecorView(),"正文字号")));tapAccessible("大字 · 18");waitForIdleSync();main(()->readingSettings.dismiss());check((Boolean)field("dark")&&((JSONObject)field("state")).optInt("textSize")==18,"dark theme and large reading size persist together");SystemClock.sleep(700);shot("dark_reading");
 main(()->{try{EditText input=(EditText)field("input");input.setText("输入内容时，发送和附件操作应保持可见。\n第二行草稿");input.requestFocus();((InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_FORCED);}catch(Exception e){throw new RuntimeException(e);}});await(()->activity.getWindow().getDecorView().getRootWindowInsets().isVisible(WindowInsets.Type.ime()),"keyboard");Rect editor=new Rect(),visible=new Rect();((EditText)field("input")).getGlobalVisibleRect(editor);activity.getWindow().getDecorView().getWindowVisibleDisplayFrame(visible);check(editor.bottom<=visible.bottom,"keyboard keeps input visible above IME");shot("keyboard");main(()->invoke("hideKeyboard"));
 main(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(()->activity.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE,"landscape");SystemClock.sleep(700);check(((Button)field("send")).isShown(),"landscape keeps primary composer action available");shot("landscape");main(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));await(()->activity.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_PORTRAIT,"portrait");store.key("");result.putString("report",report.toString());finish(Activity.RESULT_OK,result);
